"use client"

import * as React from "react"
import { BrainIcon } from "lucide-react"
import { motion, useReducedMotion } from "motion/react"

import type { MessageAnimationPreset } from "@/lib/chat/message-animations"
import { MESSAGE_ANIMATIONS } from "@/lib/chat/message-animations"
import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Message, MessageContent } from "@/components/ui/message"
import { MessageScrollerItem } from "@/components/ui/message-scroller"

// Ported from livingston-v3 apps/v4/components/message-animated.tsx. A turn
// that slides in when it arrives and stands still when it is only being
// re-rendered — the reader's turns animate, the assistant's stream in place.
// `children` is what this chat adds under the text: the run's steps and the
// Filer's widgets. The AI SDK parts array is gone; a turn here is text, and
// optionally reasoning.

type MessageAnimatedMessage = {
  id: string
  role: "user" | "assistant"
  text?: string
  reasoning?: string
}

const MotionMessageScrollerItem = motion.create(MessageScrollerItem)

function MessageAnimated({
  message,
  animationPreset = MESSAGE_ANIMATIONS["slide-up"],
  assistantVariant = "ghost",
  scrollAnchor,
  userVariant = "muted",
  children,
  text,
  ...props
}: Omit<React.ComponentProps<typeof MotionMessageScrollerItem>, "animate" | "children" | "exit" | "initial" | "messageId" | "variants"> & {
  animationPreset?: MessageAnimationPreset
  assistantVariant?: React.ComponentProps<typeof Bubble>["variant"]
  message: MessageAnimatedMessage
  userVariant?: React.ComponentProps<typeof Bubble>["variant"]
  /** Rendered in place of the plain paragraphs — the chat's own prose renderer. */
  text?: React.ReactNode
  children?: React.ReactNode
}) {
  const shouldReduceMotion = useReducedMotion()
  const isUserMessage = message.role === "user"

  const row = (
    <MessageAnimatedRow message={message} assistantVariant={assistantVariant} userVariant={userVariant} text={text}>
      {children}
    </MessageAnimatedRow>
  )

  if (isUserMessage) {
    return (
      <MotionMessageScrollerItem
        messageId={message.id}
        scrollAnchor={scrollAnchor ?? true}
        variants={animationPreset.variants}
        initial={shouldReduceMotion ? false : "initial"}
        animate="animate"
        exit={shouldReduceMotion ? undefined : "exit"}
        {...props}
      >
        {row}
      </MotionMessageScrollerItem>
    )
  }

  return (
    <MotionMessageScrollerItem messageId={message.id} scrollAnchor={scrollAnchor} initial={false} {...props}>
      {row}
    </MotionMessageScrollerItem>
  )
}

function MessageAnimatedRow({
  message,
  assistantVariant,
  userVariant,
  text,
  children,
}: {
  assistantVariant: React.ComponentProps<typeof Bubble>["variant"]
  message: MessageAnimatedMessage
  userVariant: React.ComponentProps<typeof Bubble>["variant"]
  text?: React.ReactNode
  children?: React.ReactNode
}) {
  const isUserMessage = message.role === "user"
  const paragraphs = (message.text ?? "")
    .split(/\n\s*\n/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean)

  return (
    <Message align={isUserMessage ? "end" : "start"}>
      <MessageContent>
        {message.reasoning ? (
          <div className="w-full border-l-2 border-muted-foreground/30 pl-3 text-muted-foreground">
            <div className="mb-1 flex items-center gap-1.5 text-xs font-medium">
              <BrainIcon className="size-3.5" />
              Reasoning
            </div>
            <div className="space-y-1.5 text-sm">
              {message.reasoning
                .split(/\n\s*\n/)
                .map((paragraph) => paragraph.trim())
                .filter(Boolean)
                .map((paragraph, index) => (
                  <p key={index} className="whitespace-pre-wrap">
                    {paragraph}
                  </p>
                ))}
            </div>
          </div>
        ) : null}
        {!isUserMessage && children}
        {(text || paragraphs.length > 0) && (
          <Bubble variant={isUserMessage ? userVariant : assistantVariant}>
            <BubbleContent className="space-y-2">
              {text ??
                paragraphs.map((paragraph, index) => (
                  <p key={index} className="whitespace-pre-wrap">
                    {paragraph}
                  </p>
                ))}
            </BubbleContent>
          </Bubble>
        )}
        {isUserMessage && children}
      </MessageContent>
    </Message>
  )
}

export { MessageAnimated, type MessageAnimatedMessage }

import type { Variants } from "motion/react"

// Ported from livingston-v3 apps/v4/lib/message-animations.ts: how a new
// message arrives. The chat uses slide-up; the rest are kept so the choice
// is a name, not a rewrite.

const ANIMATIONS = [
  {
    id: "fade",
    name: "Fade",
    variants: {
      initial: { opacity: 0 },
      animate: { opacity: 1, transition: { duration: 0.22, ease: "easeOut" } },
      exit: { opacity: 0, transition: { duration: 0.15 } },
    },
  },
  {
    id: "slide-up",
    name: "Slide Up",
    variants: {
      initial: { opacity: 0, y: 10 },
      animate: { opacity: 1, y: 0, transition: { duration: 0.26, ease: [0.16, 1, 0.3, 1] } },
      exit: { opacity: 0, y: 4, transition: { duration: 0.15 } },
    },
  },
  {
    id: "slide-side",
    name: "Slide Side",
    variants: {
      initial: { opacity: 0, x: 18 },
      animate: { opacity: 1, x: 0, transition: { duration: 0.28, ease: [0.16, 1, 0.3, 1] } },
      exit: { opacity: 0, x: 8, transition: { duration: 0.15 } },
    },
  },
  {
    id: "pop",
    name: "Pop",
    variants: {
      initial: { opacity: 0, scale: 0.94, y: 6, originX: 1, originY: 1 },
      animate: { opacity: 1, y: 0, scale: 1, transition: { type: "spring", stiffness: 500, damping: 34, mass: 0.7 } },
      exit: { opacity: 0, scale: 0.98, transition: { duration: 0.12 } },
    },
  },
  {
    id: "spring-bounce",
    name: "Spring Bounce",
    variants: {
      initial: { opacity: 0, y: 12, scale: 0.96 },
      animate: { opacity: 1, y: 0, scale: 1, transition: { type: "spring", stiffness: 520, damping: 30, mass: 0.7 } },
      exit: { opacity: 0, scale: 0.98, transition: { duration: 0.12 } },
    },
  },
  {
    id: "blur-fade",
    name: "Blur Fade",
    variants: {
      initial: { opacity: 0, filter: "blur(4px)", y: 6 },
      animate: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.28, ease: "easeOut" } },
      exit: { opacity: 0, filter: "blur(2px)", transition: { duration: 0.15 } },
    },
  },
  {
    id: "scale-fade",
    name: "Scale Fade",
    variants: {
      initial: { opacity: 0, scale: 0.98 },
      animate: { opacity: 1, scale: 1, transition: { duration: 0.24, ease: "easeOut" } },
      exit: { opacity: 0, scale: 0.99, transition: { duration: 0.12 } },
    },
  },
] as const satisfies { id: string; name: string; variants: Variants }[]

type MessageAnimationPreset = (typeof ANIMATIONS)[number]
type MessageAnimationId = MessageAnimationPreset["id"]

const MESSAGE_ANIMATIONS = ANIMATIONS.reduce(
  (acc, preset) => {
    acc[preset.id] = preset
    return acc
  },
  {} as Record<MessageAnimationId, MessageAnimationPreset>
)

export { MESSAGE_ANIMATIONS, type MessageAnimationId, type MessageAnimationPreset }
